cd $R/sb_rlrev && tmux new-session -d -s sb_rlrev "timeout 7200 agent -p -f --sandbox disabled --trust --model claude-opus-5-5-xhigh 'Read PROMPT.md in this folder and carry out the task it describes, completely.' > cursor.log 2>&1"
mkdir -p $R/sb_regenscope/prompts $R/sb_regenscope/out
echo  | base64 -d > $R/sb_regenscope/prompts/sb_regenscope.md
